head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[localStorage > M > removeItem]<br/>localStorage 에서 파라미터에 해당하는 데이터를 삭제합니다.",
    "validation" : [
        "key(필수) 파라미터로 삭제할 항목의 키 이름을 설정할 수 있어야 합니다.",
        "key 파라미터에 해당하는 데이터가 삭제되어야 합니다.",
        "삭제 후 getItem() 으로 조회하면 null 이 반환되어야 합니다.",
        "존재하지 않는 키를 전달해도 에러가 발생하지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 기존 데이터 초기화 후 테스트 데이터 저장
    WebSquare.localStorage.clear();
    WebSquare.localStorage.setItem("removeTest1", "삭제대상값1");
    WebSquare.localStorage.setItem("removeTest2", "삭제대상값2");
};



scwin.btn_removeItem_onclick = function () {
    let key = par_key.getValue();

    // 삭제 전 값 확인
    let before = WebSquare.localStorage.getItem(key);
    wf_body_bottom.getObj("scwin").setReturnValue("삭제 전 getItem('" + key + "') : " + before);

    // 삭제
    WebSquare.localStorage.removeItem(key);

    // 삭제 후 값 확인
    let after = WebSquare.localStorage.getItem(key);
    wf_body_bottom.getObj("scwin").setReturnValue("삭제 후 getItem('" + key + "') : " + after);

    if (before !== null && after === null) {
        wf_body_bottom.getObj("scwin").setReturnValue("삭제 확인 : PASS");
    } else if (before === null) {
        wf_body_bottom.getObj("scwin").setReturnValue("존재하지 않는 키 삭제 → 에러 없이 처리 : PASS");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("삭제 확인 : FAIL");
    }
}
